// Stage 1: Fast SQL-based Pre-filtering
// This reduces candidates by 80-90% using basic criteria

const users = $('Get New Users').first().json.users;
const products = $('Get Loan Products').first().json.products;

const matches = [];

for (const user of users) {
  for (const product of products) {
    // Fast pre-filtering logic
    let isEligible = true;
    let matchReasons = [];
    let disqualifyReasons = [];

    // Income check
    if (product.min_monthly_income && user.monthly_income) {
      if (user.monthly_income < product.min_monthly_income) {
        disqualifyReasons.push(`Income ${user.monthly_income} < required ${product.min_monthly_income}`);
        isEligible = false;
      } else {
        matchReasons.push('Income requirement met');
      }
    }

    // Credit score check
    if (product.min_credit_score && user.credit_score) {
      if (user.credit_score < product.min_credit_score) {
        disqualifyReasons.push(`Credit score ${user.credit_score} < required ${product.min_credit_score}`);
        isEligible = false;
      } else {
        matchReasons.push('Credit score requirement met');
      }
    }

    // Age check
    if (product.min_age && product.max_age && user.age) {
      if (user.age < product.min_age || user.age > product.max_age) {
        disqualifyReasons.push(`Age ${user.age} not in range ${product.min_age}-${product.max_age}`);
        isEligible = false;
      } else {
        matchReasons.push('Age requirement met');
      }
    }

    // Employment status check
    if (product.employment_types && product.employment_types.length > 0) {
      const userEmployment = user.employment_status?.toLowerCase();
      const acceptedTypes = product.employment_types.map(type => type.toLowerCase());

      if (!acceptedTypes.includes(userEmployment)) {
        disqualifyReasons.push(`Employment ${user.employment_status} not accepted`);
        isEligible = false;
      } else {
        matchReasons.push('Employment requirement met');
      }
    }

    // Only proceed with eligible matches for Stage 2
    if (isEligible) {
      // Calculate basic match score (0-1)
      let matchScore = 0.0;
      let scoreComponents = 0;

      // Income score component
      if (product.min_monthly_income && user.monthly_income) {
        const incomeRatio = user.monthly_income / product.min_monthly_income;
        matchScore += Math.min(incomeRatio / 2, 0.3); // Max 0.3 for income
        scoreComponents++;
      }

      // Credit score component
      if (product.min_credit_score && user.credit_score) {
        const creditRatio = (user.credit_score - 300) / (850 - 300); // Normalize to 0-1
        matchScore += creditRatio * 0.4; // Max 0.4 for credit score
        scoreComponents++;
      }

      // Age component (younger is generally better for loans)
      if (product.min_age && product.max_age && user.age) {
        const ageScore = 1 - ((user.age - product.min_age) / (product.max_age - product.min_age));
        matchScore += ageScore * 0.2; // Max 0.2 for age
        scoreComponents++;
      }

      // Employment bonus
      if (user.employment_status === 'Salaried') {
        matchScore += 0.1;
      }

      matchScore = Math.min(matchScore, 1.0);

      matches.push({
        user_id: user.user_id,
        product_id: product.product_id,
        match_score: Math.round(matchScore * 100) / 100,
        eligibility_status: 'eligible',
        match_reasons: matchReasons,
        user_data: user,
        product_data: product,
        stage: 'pre_filtered'
      });
    }
  }
}

console.log(`Stage 1 Pre-filtering: ${matches.length} potential matches from ${users.length * products.length} combinations`);

return matches.map(match => ({ json: match }));

// Stage 2: Advanced Matching Logic
// Apply more sophisticated criteria and scoring

const matches = $input.all().map(item => item.json);
const advancedMatches = [];

for (const match of matches) {
  const user = match.user_data;
  const product = match.product_data;
  let advancedScore = match.match_score;
  let advancedReasons = [...match.match_reasons];

  // Advanced scoring factors

  // 1. Income-to-EMI ratio (30% of income should cover EMI)
  if (user.monthly_income && product.loan_amount_max && product.interest_rate_max) {
    const assumedLoanAmount = Math.min(user.monthly_income * 60, product.loan_amount_max); // 60x income or max amount
    const monthlyRate = (product.interest_rate_max / 100) / 12;
    const tenure = 36; // 3 years default
    const emi = (assumedLoanAmount * monthlyRate * Math.pow(1 + monthlyRate, tenure)) / (Math.pow(1 + monthlyRate, tenure) - 1);
    const emiRatio = emi / user.monthly_income;

    if (emiRatio <= 0.3) {
      advancedScore += 0.1;
      advancedReasons.push('Good EMI-to-income ratio');
    } else if (emiRatio <= 0.4) {
      advancedReasons.push('Acceptable EMI-to-income ratio');
    } else {
      advancedScore -= 0.1;
      advancedReasons.push('High EMI-to-income ratio');
    }
  }

  // 2. Credit score excellence bonus
  if (user.credit_score >= 750) {
    advancedScore += 0.15;
    advancedReasons.push('Excellent credit score');
  } else if (user.credit_score >= 700) {
    advancedScore += 0.05;
    advancedReasons.push('Good credit score');
  }

  // 3. Interest rate attractiveness (lower rates get higher scores)
  if (product.interest_rate_min) {
    if (product.interest_rate_min <= 10) {
      advancedScore += 0.1;
      advancedReasons.push('Very competitive interest rate');
    } else if (product.interest_rate_min <= 15) {
      advancedScore += 0.05;
      advancedReasons.push('Competitive interest rate');
    }
  }

  // 4. Employment stability bonus
  if (user.employment_status === 'Salaried' && user.monthly_income >= 50000) {
    advancedScore += 0.05;
    advancedReasons.push('Stable high-income employment');
  }

  // Cap the score at 1.0
  advancedScore = Math.min(advancedScore, 1.0);

  // Only keep high-quality matches (score >= 0.6)
  if (advancedScore >= 0.6) {
    advancedMatches.push({
      user_id: match.user_id,
      product_id: match.product_id,
      match_score: Math.round(advancedScore * 100) / 100,
      eligibility_status: advancedScore >= 0.8 ? 'eligible' : 'partially_eligible',
      match_reasons: advancedReasons,
      stage: 'advanced_filtered'
    });
  }
}

console.log(`Stage 2 Advanced Filtering: ${advancedMatches.length} high-quality matches from ${matches.length} pre-filtered`);

return advancedMatches.map(match => ({ json: match }));

// Stage 3: AI Analysis (Only for top matches)
// Select top 20% of matches for expensive AI analysis

const matches = $input.all().map(item => item.json);

// Sort by score and take top 20% or max 50 matches
const sortedMatches = matches.sort((a, b) => b.match_score - a.match_score);
const topCount = Math.min(Math.ceil(sortedMatches.length * 0.2), 50);
const topMatches = sortedMatches.slice(0, topCount);
const remainingMatches = sortedMatches.slice(topCount);

console.log(`Stage 3 AI Selection: ${topMatches.length} matches selected for AI analysis out of ${matches.length}`);

// Return both sets with different flags
const results = [];

// Top matches for AI analysis
topMatches.forEach(match => {
  results.push({
    json: {
      ...match,
      needs_ai_analysis: true,
      stage: 'ai_candidate'
    }
  });
});

// Remaining matches go directly to storage
remainingMatches.forEach(match => {
  results.push({
    json: {
      ...match,
      needs_ai_analysis: false,
      stage: 'final_match'
    }
  });
});

return results;

