// Process AI results and combine with match data
const match = $('Route AI Matches').first().json;
const aiResponse = $input.first().json.choices[0].message.content;

try {
  const aiAnalysis = JSON.parse(aiResponse);

  const finalMatch = {
    user_id: match.user_id,
    product_id: match.product_id,
    match_score: aiAnalysis.refined_score || match.match_score,
    eligibility_status: aiAnalysis.eligibility_status || match.eligibility_status,
    match_reasons: match.match_reasons,
    ai_analysis: `${aiAnalysis.ai_insights} | Recommendations: ${aiAnalysis.recommendations}`,
    stage: 'ai_analyzed'
  };

  return [{ json: finalMatch }];
} catch (error) {
  console.log('AI parsing error, using original match:', error);
  return [{ json: {
    ...match,
    ai_analysis: 'AI analysis failed - using original scoring',
    stage: 'ai_failed'
  } }];
}
